*** Begin Patch
*** Add File: /app/ars.R
+# Adaptive rejection sampling (ARS), following Gilks and Wild (1992).
+# The target argument is a vectorized density function (or expression); use
+# log=TRUE for an already-logarithmic target. Support endpoints may be infinite.
+
+ars_validate <- function(target, n, domain, initial, log, max_iter, tol) {
+  if (!is.function(target) && !is.expression(target) && !is.call(target)) {
+    stop("target must be a function or an R expression/call", call. = FALSE)
+  }
+  if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) ||
+      n < 0 || n != floor(n)) {
+    stop("n must be one finite, non-negative integer", call. = FALSE)
+  }
+  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) ||
+      domain[1L] >= domain[2L]) {
+    stop("domain must be c(lower, upper) with lower < upper", call. = FALSE)
+  }
+  if (!is.numeric(initial) || length(initial) < 2L || any(!is.finite(initial)) ||
+      is.unsorted(initial, strictly = TRUE) || any(initial <= domain[1L]) ||
+      any(initial >= domain[2L])) {
+    stop("initial must contain at least two strictly increasing finite points inside domain", call. = FALSE)
+  }
+  if (length(log) != 1L || is.na(log) || !is.logical(log)) {
+    stop("log must be TRUE or FALSE", call. = FALSE)
+  }
+  if (length(max_iter) != 1L || !is.numeric(max_iter) || !is.finite(max_iter) ||
+      max_iter < 1 || max_iter != floor(max_iter)) {
+    stop("max_iter must be a positive integer", call. = FALSE)
+  }
+  if (length(tol) != 1L || !is.numeric(tol) || !is.finite(tol) || tol <= 0) {
+    stop("tol must be a positive finite number", call. = FALSE)
+  }
+  invisible(TRUE)
+}
+
+ars_make_log_density <- function(target, log, envir) {
+  if (is.expression(target) || is.call(target)) {
+    expr <- target
+    if (is.expression(expr)) {
+      if (length(expr) != 1L) stop("target expression must contain exactly one expression", call. = FALSE)
+      expr <- expr[[1L]]
+    }
+    fn <- eval(substitute(function(x) EXPR, list(EXPR = expr)), envir = envir)
+  } else {
+    fn <- target
+  }
+  function(x) {
+    value <- tryCatch(fn(x), error = function(e) {
+      stop(sprintf("target evaluation failed: %s", conditionMessage(e)), call. = FALSE)
+    })
+    if (!is.numeric(value) || length(value) != length(x)) {
+      stop("target must return one numeric value per input x", call. = FALSE)
+    }
+    if (log) {
+      out <- as.numeric(value)
+    } else {
+      if (any(value < 0, na.rm = TRUE)) stop("density target returned negative values", call. = FALSE)
+      out <- log(as.numeric(value))
+    }
+    if (any(is.na(out)) || any(out == Inf)) {
+      stop("log density returned NA or +Inf", call. = FALSE)
+    }
+    out
+  }
+}
+
+ars_eval_derivative <- function(log_density, x, h = 1e-5) {
+  # Centered differences where possible, with one-sided differences at support edges.
+  f0 <- log_density(x)
+  fp <- log_density(x + h)
+  fm <- log_density(x - h)
+  deriv <- (fp - fm) / (2 * h)
+  use_forward <- is.finite(fp) & !is.finite(fm)
+  use_backward <- !is.finite(fp) & is.finite(fm)
+  deriv[use_forward] <- (fp[use_forward] - f0[use_forward]) / h
+  deriv[use_backward] <- (f0[use_backward] - fm[use_backward]) / h
+  deriv
+}
+
+ars_check_concavity <- function(x, y, slopes, tol = 1e-7) {
+  if (any(!is.finite(y)) || any(!is.finite(slopes))) {
+    stop("log-concavity check failed: initial points must have finite log density and derivative", call. = FALSE)
+  }
+  if (length(slopes) > 1L && any(diff(slopes) > tol * (1 + abs(slopes[-length(slopes)])))) {
+    stop("target appears non-log-concave: log-density derivative increases between support points", call. = FALSE)
+  }
+  invisible(TRUE)
+}
+
+ars_build_hull <- function(x, y, slopes, domain) {
+  k <- length(x)
+  z <- numeric(k + 1L)
+  z[1L] <- domain[1L]
+  z[k + 1L] <- domain[2L]
+  if (k > 1L) {
+    for (i in seq_len(k - 1L)) {
+      denom <- slopes[i] - slopes[i + 1L]
+      if (!is.finite(denom) || denom <= 0) {
+        stop("target appears non-log-concave: invalid tangent intersection", call. = FALSE)
+      }
+      z[i + 1L] <- (y[i + 1L] - y[i] + slopes[i] * x[i] - slopes[i + 1L] * x[i + 1L]) / denom
+      if (!is.finite(z[i + 1L]) || z[i + 1L] <= x[i] || z[i + 1L] >= x[i + 1L]) {
+        stop("failed to construct a valid tangent envelope; check target concavity and initial points", call. = FALSE)
+      }
+    }
+  }
+  if (any(diff(z) <= 0)) stop("invalid tangent-envelope intervals", call. = FALSE)
+  log_area <- numeric(k)
+  for (i in seq_len(k)) {
+    a <- z[i]
+    b <- z[i + 1L]
+    s <- slopes[i]
+    if (abs(s) < 1e-12) {
+      log_area[i] <- y[i] + log(b - a)
+    } else if (s > 0) {
+      if (is.infinite(b)) stop("upper hull is not integrable on the right; provide a valid concave tail", call. = FALSE)
+      log_area[i] <- y[i] + s * (b - x[i]) + log1p(-exp(s * (a - b))) - log(s)
+    } else {
+      if (is.infinite(a)) stop("upper hull is not integrable on the left; provide a valid concave tail", call. = FALSE)
+      log_area[i] <- y[i] + s * (a - x[i]) + log1p(-exp(s * (b - a))) - log(-s)
+    }
+  }
+  shift <- max(log_area)
+  weights <- exp(log_area - shift)
+  list(x = x, y = y, slopes = slopes, knots = z,
+       weights = weights / sum(weights), log_area = log_area, shift = shift)
+}
+
+ars_draw_hull <- function(hull) {
+  i <- sample.int(length(hull$weights), 1L, prob = hull$weights)
+  a <- hull$knots[i]
+  b <- hull$knots[i + 1L]
+  s <- hull$slopes[i]
+  u <- runif(1L)
+  if (abs(s) < 1e-12) {
+    x <- a + u * (b - a)
+  } else if (s > 0) {
+    x <- b + log(u + (1 - u) * exp(s * (a - b))) / s
+  } else {
+    x <- a + log((1 - u) + u * exp(s * (b - a))) / s
+  }
+  log_hull <- hull$y[i] + s * (x - hull$x[i])
+  list(x = x, log_hull = log_hull, interval = i)
+}
+
+ars <- function(target, n, domain = c(-Inf, Inf), initial = NULL,
+                log = FALSE, max_iter = max(10000L, 1000L * max(1, n)),
+                tol = 1e-7, envir = parent.frame()) {
+  if (is.null(initial)) {
+    if (all(is.finite(domain))) {
+      initial <- seq(domain[1L] + (domain[2L] - domain[1L]) / 3,
+                     domain[2L] - (domain[2L] - domain[1L]) / 3, length.out = 2L)
+    } else if (is.finite(domain[1L]) && is.infinite(domain[2L])) {
+      initial <- domain[1L] + c(0.5, 1.5)
+    } else if (is.infinite(domain[1L]) && is.finite(domain[2L])) {
+      initial <- domain[2L] - c(1.5, 0.5)
+    } else {
+      initial <- c(-1, 1)
+    }
+  }
+  ars_validate(target, n, domain, initial, log, max_iter, tol)
+  if (n == 0) return(numeric(0))
+  log_density <- ars_make_log_density(target, log, envir)
+  x <- as.numeric(initial)
+  y <- log_density(x)
+  if (any(!is.finite(y))) stop("initial points must be inside the positive-density support", call. = FALSE)
+  slopes <- ars_eval_derivative(log_density, x)
+  ars_check_concavity(x, y, slopes, tol)
+
+  samples <- numeric(n)
+  n_accepted <- 0L
+  iter <- 0L
+  while (n_accepted < n && iter < max_iter) {
+    iter <- iter + 1L
+    hull <- ars_build_hull(x, y, slopes, domain)
+    draw <- ars_draw_hull(hull)
+    candidate <- draw$x
+    candidate_log <- log_density(candidate)
+    if (is.finite(candidate_log) && candidate_log > draw$log_hull + tol * (1 + abs(draw$log_hull))) {
+      stop("target exceeded its tangent upper hull; target may not be log-concave", call. = FALSE)
+    }
+    # Squeeze lower hull from adjacent secant line.
+    lower <- -Inf
+    if (length(x) > 1L && candidate > x[1L] && candidate < x[length(x)]) {
+      j <- findInterval(candidate, x)
+      j <- max(1L, min(j, length(x) - 1L))
+      lower <- y[j] + (y[j + 1L] - y[j]) * (candidate - x[j]) / (x[j + 1L] - x[j])
+    }
+    logu <- log(runif(1L))
+    accepted <- logu <= lower - draw$log_hull
+    if (!accepted) accepted <- logu <= candidate_log - draw$log_hull
+    if (accepted) {
+      n_accepted <- n_accepted + 1L
+      samples[n_accepted] <- candidate
+    }
+    # Adapt the envelope using every candidate where the target is finite.
+    if (is.finite(candidate_log) && all(abs(x - candidate) > .Machine$double.eps^0.5 * (1 + abs(candidate)))) {
+      new_slope <- ars_eval_derivative(log_density, candidate)
+      x_new <- sort(c(x, candidate))
+      y_new <- log_density(x_new)
+      slope_new <- ars_eval_derivative(log_density, x_new)
+      ars_check_concavity(x_new, y_new, slope_new, tol)
+      x <- x_new
+      y <- y_new
+      slopes <- slope_new
+    }
+  }
+  if (n_accepted < n) stop(sprintf("maximum iteration count (%d) reached before obtaining %d samples", max_iter, n), call. = FALSE)
+  samples
+}
+
+test <- function(seed = 20261003, n = 10000L, sample_file = "/app/normal_samples.txt") {
+  set.seed(seed)
+  results <- list()
+  report <- function(name, passed, sample = numeric(), detail = "") {
+    mu <- if (length(sample)) mean(sample) else NA_real_
+    sigma <- if (length(sample) > 1L) sd(sample) else NA_real_
+    status <- if (isTRUE(passed)) "PASS" else "FAIL"
+    cat(sprintf("%s: %s | mean=%.5f sd=%.5f%s\n", name, status, mu, sigma,
+                if (nzchar(detail)) paste0(" | ", detail) else ""))
+    results[[name]] <<- isTRUE(passed)
+  }
+  normal <- tryCatch(ars(function(x) dnorm(x), n, initial = c(-1, 1)), error = identity)
+  if (inherits(normal, "error")) {
+    report("NORMAL_N01", FALSE, detail = conditionMessage(normal))
+  } else {
+    report("NORMAL_N01", abs(mean(normal)) < 0.06 && abs(sd(normal) - 1) < 0.06, normal,
+           "truth: mean=0, sd=1; tolerances=0.06")
+    tryCatch(write.table(normal, file = sample_file, row.names = FALSE, col.names = FALSE),
+             error = function(e) report("SAMPLE_FILE", FALSE, normal, conditionMessage(e)))
+    if (file.exists(sample_file)) report("SAMPLE_FILE", length(readLines(sample_file)) == length(normal), normal,
+                                          paste("written:", sample_file))
+  }
+  set.seed(seed + 1L)
+  exponential <- tryCatch(ars(function(x) dexp(x, rate = 2), n, domain = c(0, Inf),
+                             initial = c(0.25, 1)), error = identity)
+  if (inherits(exponential, "error")) {
+    report("EXPONENTIAL_RATE2", FALSE, detail = conditionMessage(exponential))
+  } else {
+    report("EXPONENTIAL_RATE2", all(exponential >= 0) && abs(mean(exponential) - 0.5) < 0.04 &&
+             abs(sd(exponential) - 0.5) < 0.04, exponential,
+           "truth: mean=0.5, sd=0.5; support=[0, Inf); tolerances=0.04")
+  }
+  invalid_count <- inherits(tryCatch(ars(function(x) dnorm(x), -1), error = identity), "error")
+  report("INVALID_COUNT_REJECTED", invalid_count)
+  bad_domain <- inherits(tryCatch(ars(function(x) dnorm(x), 5, domain = c(1, 1)), error = identity), "error")
+  report("INVALID_DOMAIN_REJECTED", bad_domain)
+  nonconcave <- inherits(tryCatch(ars(function(x) exp(x^2), 5, initial = c(-1, 1)), error = identity), "error")
+  report("NON_LOG_CONCAVE_REJECTED", nonconcave, detail = "convex log-density must be rejected")
+  invisible(all(unlist(results)))
+}
*** End Patch

