expression(ars_validate <- function(target, n, domain, initial, 
    log, max_iter, tol) {
    if (!is.function(target) && !is.expression(target) && !is.call(target)) {
        stop("target must be a function or an R expression/call", 
            call. = FALSE)
    }
    if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) || 
        n < 0 || n != floor(n)) {
        stop("n must be one finite, non-negative integer", call. = FALSE)
    }
    if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) || 
        domain[1L] >= domain[2L]) {
        stop("domain must be c(lower, upper) with lower < upper", 
            call. = FALSE)
    }
    if (!is.numeric(initial) || length(initial) < 2L || any(!is.finite(initial)) || 
        is.unsorted(initial, strictly = TRUE) || any(initial <= 
        domain[1L]) || any(initial >= domain[2L])) {
        stop("initial must contain at least two strictly increasing finite points inside domain", 
            call. = FALSE)
    }
    if (length(log) != 1L || is.na(log) || !is.logical(log)) {
        stop("log must be TRUE or FALSE", call. = FALSE)
    }
    if (length(max_iter) != 1L || !is.numeric(max_iter) || !is.finite(max_iter) || 
        max_iter < 1 || max_iter != floor(max_iter)) {
        stop("max_iter must be a positive integer", call. = FALSE)
    }
    if (length(tol) != 1L || !is.numeric(tol) || !is.finite(tol) || 
        tol <= 0) {
        stop("tol must be a positive finite number", call. = FALSE)
    }
    invisible(TRUE)
}, ars_make_log_density <- function(target, log, envir) {
    if (is.expression(target) || is.call(target)) {
        expr <- target
        if (is.expression(expr)) {
            if (length(expr) != 1L) 
                stop("target expression must contain exactly one expression", 
                  call. = FALSE)
            expr <- expr[[1L]]
        }
        fn <- eval(substitute(function(x) EXPR, list(EXPR = expr)), 
            envir = envir)
    }
    else {
        fn <- target
    }
    function(x) {
        value <- tryCatch(fn(x), error = function(e) {
            stop(sprintf("target evaluation failed: %s", conditionMessage(e)), 
                call. = FALSE)
        })
        if (!is.numeric(value) || length(value) != length(x)) {
            stop("target must return one numeric value per input x", 
                call. = FALSE)
        }
        if (log) {
            out <- as.numeric(value)
        }
        else {
            if (any(value < 0, na.rm = TRUE)) 
                stop("density target returned negative values", 
                  call. = FALSE)
            out <- log(as.numeric(value))
        }
        if (any(is.na(out)) || any(out == Inf)) {
            stop("log density returned NA or +Inf", call. = FALSE)
        }
        out
    }
}, ars_eval_derivative <- function(log_density, x, h = 1e-05) {
    f0 <- log_density(x)
    fp <- log_density(x + h)
    fm <- log_density(x - h)
    deriv <- (fp - fm)/(2 * h)
    use_forward <- is.finite(fp) & !is.finite(fm)
    use_backward <- !is.finite(fp) & is.finite(fm)
    deriv[use_forward] <- (fp[use_forward] - f0[use_forward])/h
    deriv[use_backward] <- (f0[use_backward] - fm[use_backward])/h
    deriv
}, ars_check_concavity <- function(x, y, slopes, tol = 1e-07) {
    if (any(!is.finite(y)) || any(!is.finite(slopes))) {
        stop("log-concavity check failed: initial points must have finite log density and derivative", 
            call. = FALSE)
    }
    if (length(slopes) > 1L && any(diff(slopes) > tol * (1 + 
        abs(slopes[-length(slopes)])))) {
        stop("target appears non-log-concave: log-density derivative increases between support points", 
            call. = FALSE)
    }
    invisible(TRUE)
}, ars_build_hull <- function(x, y, slopes, domain) {
    k <- length(x)
    z <- numeric(k + 1L)
    z[1L] <- domain[1L]
    z[k + 1L] <- domain[2L]
    if (k > 1L) {
        for (i in seq_len(k - 1L)) {
            denom <- slopes[i] - slopes[i + 1L]
            if (!is.finite(denom) || denom < -1e-07 * (1 + max(abs(slopes)))) {
                stop("target appears non-log-concave: invalid tangent intersection", 
                  call. = FALSE)
            }
            if (denom <= 1e-07 * (1 + max(abs(slopes)))) {
                z[i + 1L] <- x[i + 1L]
            }
            else {
                z[i + 1L] <- (y[i + 1L] - y[i] + slopes[i] * 
                  x[i] - slopes[i + 1L] * x[i + 1L])/denom
            }
            if (!is.finite(z[i + 1L]) || z[i + 1L] < z[i] - 1e-08 * 
                (1 + abs(z[i]))) {
                stop("failed to construct a valid tangent envelope; check target concavity and initial points", 
                  call. = FALSE)
            }
        }
    }
    if (any(diff(z) < 0)) 
        stop("invalid tangent-envelope intervals", call. = FALSE)
    log_area <- numeric(k)
    for (i in seq_len(k)) {
        a <- z[i]
        b <- z[i + 1L]
        s <- slopes[i]
        if (b == a) {
            log_area[i] <- -Inf
        }
        else if (abs(s) < 1e-12) {
            log_area[i] <- y[i] + log(b - a)
        }
        else if (s > 0) {
            if (is.infinite(b)) 
                stop("upper hull is not integrable on the right; provide a valid concave tail", 
                  call. = FALSE)
            log_area[i] <- y[i] + s * (b - x[i]) + log1p(-exp(s * 
                (a - b))) - log(s)
        }
        else {
            if (is.infinite(a)) 
                stop("upper hull is not integrable on the left; provide a valid concave tail", 
                  call. = FALSE)
            log_area[i] <- y[i] + s * (a - x[i]) + log1p(-exp(s * 
                (b - a))) - log(-s)
        }
    }
    shift <- max(log_area)
    weights <- exp(log_area - shift)
    list(x = x, y = y, slopes = slopes, knots = z, weights = weights/sum(weights), 
        log_area = log_area, shift = shift)
}, ars_draw_hull <- function(hull) {
    i <- sample.int(length(hull$weights), 1L, prob = hull$weights)
    a <- hull$knots[i]
    b <- hull$knots[i + 1L]
    s <- hull$slopes[i]
    u <- runif(1L)
    if (abs(s) < 1e-12) {
        x <- a + u * (b - a)
    }
    else if (s > 0) {
        x <- b + log(u + (1 - u) * exp(s * (a - b)))/s
    }
    else {
        x <- a + log((1 - u) + u * exp(s * (b - a)))/s
    }
    log_hull <- hull$y[i] + s * (x - hull$x[i])
    list(x = x, log_hull = log_hull, interval = i)
}, ars <- function(target, n, domain = c(-Inf, Inf), initial = NULL, 
    log = FALSE, max_iter = max(10000L, 1000L * max(1, n)), tol = 1e-07, 
    envir = parent.frame()) {
    if (is.null(initial)) {
        if (all(is.finite(domain))) {
            initial <- seq(domain[1L] + (domain[2L] - domain[1L])/3, 
                domain[2L] - (domain[2L] - domain[1L])/3, length.out = 2L)
        }
