    set.seed(seed)
    results <- list()
    report <- function(name, passed, sample = numeric(), detail = "") {
        mu <- if (length(sample)) 
            mean(sample)
        else NA_real_
        sigma <- if (length(sample) > 1L) 
            sd(sample)
        else NA_real_
        status <- if (isTRUE(passed)) 
            "PASS"
        else "FAIL"
        cat(sprintf("%s: %s | mean=%.5f sd=%.5f%s\n", name, status, 
            mu, sigma, if (nzchar(detail)) 
                paste0(" | ", detail)
            else ""))
        results[[name]] <<- isTRUE(passed)
    }
    normal <- tryCatch(ars(function(x) dnorm(x), n, initial = c(-1, 
        1)), error = identity)
    if (inherits(normal, "error")) {
        report("NORMAL_N01", FALSE, detail = conditionMessage(normal))
    }
    else {
        report("NORMAL_N01", abs(mean(normal)) < 0.06 && abs(sd(normal) - 
            1) < 0.06, normal, "truth: mean=0, sd=1; tolerances=0.06")
        tryCatch(write.table(normal, file = sample_file, row.names = FALSE, 
            col.names = FALSE), error = function(e) report("SAMPLE_FILE", 
            FALSE, normal, conditionMessage(e)))
        if (file.exists(sample_file)) 
            report("SAMPLE_FILE", length(readLines(sample_file)) == 
                length(normal), normal, paste("written:", sample_file))
    }
    set.seed(seed + 1L)
    exponential <- tryCatch(ars(function(x) dexp(x, rate = 2), 
        n, domain = c(0, Inf), initial = c(0.25, 1)), error = identity)
    if (inherits(exponential, "error")) {
        report("EXPONENTIAL_RATE2", FALSE, detail = conditionMessage(exponential))
    }
    else {
        report("EXPONENTIAL_RATE2", all(exponential >= 0) && 
            abs(mean(exponential) - 0.5) < 0.04 && abs(sd(exponential) - 
            0.5) < 0.04, exponential, "truth: mean=0.5, sd=0.5; support=[0, Inf); tolerances=0.04")
    }
    invalid_count <- inherits(tryCatch(ars(function(x) dnorm(x), 
        -1), error = identity), "error")
    report("INVALID_COUNT_REJECTED", invalid_count)
    bad_domain <- inherits(tryCatch(ars(function(x) dnorm(x), 
        5, domain = c(1, 1)), error = identity), "error")
    report("INVALID_DOMAIN_REJECTED", bad_domain)
    nonconcave <- inherits(tryCatch(ars(function(x) exp(x^2), 
        5, initial = c(-1, 1)), error = identity), "error")
    report("NON_LOG_CONCAVE_REJECTED", nonconcave, detail = "convex log-density must be rejected")
    invisible(all(unlist(results)))
})
