expression(ars_logspace_add <- function(a, b) {
    if (is.infinite(a) && a < 0) 
        return(b)
    if (is.infinite(b) && b < 0) 
        return(a)
    m <- max(a, b)
    m + log(exp(a - m) + exp(b - m))
}, ars_eval_log_density <- function(target, x, log) {
    values <- tryCatch(target(x), error = function(e) {
        stop("target function failed: ", conditionMessage(e), 
            call. = FALSE)
    })
    if (!is.numeric(values) || length(values) != length(x)) {
        stop("target function must return one numeric value per input", 
            call. = FALSE)
    }
    values <- as.numeric(values)
    if (anyNA(values) || any(values == Inf)) {
        stop("target function returned NA or positive infinity", 
            call. = FALSE)
    }
    if (log) {
        values
    }
    else {
        if (any(values < 0)) 
            stop("density values must be nonnegative", call. = FALSE)
        log(values)
    }
}, ars_eval_derivative <- function(target, x, log, lower, upper) {
    step <- .Machine$double.eps^(1/3) * (1 + abs(x))
    left <- max(lower, x - step)
    right <- min(upper, x + step)
    if (!is.finite(left)) 
        left <- x - step
    if (!is.finite(right)) 
        right <- x + step
    if (left >= x || right <= x) {
        stop("cannot estimate target derivative at a domain boundary", 
            call. = FALSE)
    }
    vals <- ars_eval_log_density(target, c(left, right), log)
    if (!is.finite(vals[1]) || !is.finite(vals[2])) {
        stop("target must have finite log density at initial support points", 
            call. = FALSE)
    }
    slope <- (vals[2] - vals[1])/(right - left)
    if (!is.finite(slope)) 
        stop("could not estimate a finite target derivative", 
            call. = FALSE)
    slope
}, ars_intersections <- function(x, h, dh, lower, upper, tolerance = 1e-10) {
    n <- length(x)
    if (n < 2L) 
        return(numeric())
    z <- numeric(n + 1L)
    z[1] <- lower
    z[n + 1L] <- upper
    for (i in seq_len(n - 1L)) {
        denom <- dh[i] - dh[i + 1L]
        if (denom < -tolerance) {
            stop("target is not log-concave: tangent slopes are not strictly decreasing", 
                call. = FALSE)
        }
        if (abs(denom) <= tolerance) {
            if (abs((h[i] - dh[i] * x[i]) - (h[i + 1L] - dh[i + 
                1L] * x[i + 1L])) > 1e-07) {
                stop("target is not log-concave: parallel tangents have inconsistent intercepts", 
                  call. = FALSE)
            }
            z[i + 1L] <- (x[i] + x[i + 1L])/2
        }
        else {
            z[i + 1L] <- (h[i + 1L] - h[i] + dh[i] * x[i] - dh[i + 
                1L] * x[i + 1L])/denom
        }
        if (!is.finite(z[i + 1L]) || z[i + 1L] <= x[i] || z[i + 
            1L] >= x[i + 1L]) {
            stop("target is not log-concave or has numerically invalid tangent intersections", 
                call. = FALSE)
        }
    }
    z
}, ars_envelope <- function(x, h, dh, lower, upper) {
    z <- ars_intersections(x, h, dh, lower, upper)
    left <- z[-length(z)]
    right <- z[-1L]
    log_mass <- numeric(length(x))
    for (i in seq_along(x)) {
        slope <- dh[i]
        intercept <- h[i] - slope * x[i]
        a <- left[i]
        b <- right[i]
        if (!is.finite(a)) {
            if (slope <= 0) 
                stop("left tail envelope has infinite mass; use a support point with positive slope", 
                  call. = FALSE)
            log_mass[i] <- intercept + slope * b - log(slope)
        }
        else if (!is.finite(b)) {
            if (slope >= 0) 
                stop("right tail envelope has infinite mass; use a support point with negative slope", 
                  call. = FALSE)
            log_mass[i] <- intercept + slope * a - log(-slope)
        }
        else if (abs(slope) < 1e-12) {
            log_mass[i] <- intercept + log(b - a)
        }
        else {
            hi <- max(slope * a, slope * b)
            lo <- min(slope * a, slope * b)
            log_mass[i] <- intercept + hi + log1p(-exp(lo - hi)) - 
                log(abs(slope))
        }
    }
    if (any(!is.finite(log_mass))) 
        stop("could not construct a finite envelope", call. = FALSE)
    list(left = left, right = right, log_mass = log_mass)
}, ars_draw_envelope <- function(envelope, x, h, dh) {
    masses <- exp(envelope$log_mass - max(envelope$log_mass))
    segment <- sample.int(length(masses), size = 1L, prob = masses)
    a <- envelope$left[segment]
    b <- envelope$right[segment]
    slope <- dh[segment]
    if (!is.finite(a)) {
        value <- b + log(runif(1))/slope
    }
    else if (!is.finite(b)) {
        value <- a + log(runif(1))/slope
    }
    else if (abs(slope) < 1e-12) {
        value <- runif(1, a, b)
    }
    else {
        ea <- exp(slope * a)
        eb <- exp(slope * b)
        value <- log(ea + runif(1) * (eb - ea))/slope
    }
    upper <- h[segment] + slope * (value - x[segment])
    list(x = value, upper = upper)
}, ars <- function(target, n, initial, domain = c(-Inf, Inf), 
    log = TRUE, max_iterations = max(10000L, 1000L * n), seed = NULL) {
    if (!is.function(target)) 
        stop("target must be a function", call. = FALSE)
    if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) || 
        n < 0 || n != floor(n)) 
        stop("n must be a nonnegative integer", call. = FALSE)
    if (length(log) != 1L || !is.logical(log) || is.na(log)) 
        stop("log must be TRUE or FALSE", call. = FALSE)
    if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) || 
        domain[1] >= domain[2]) 
        stop("domain must be an increasing numeric pair", call. = FALSE)
    if (!is.numeric(initial) || length(initial) < 2L || any(!is.finite(initial)) || 
        anyDuplicated(initial) || any(initial <= domain[1] | 
        initial >= domain[2])) {
        stop("initial must contain at least two distinct finite points strictly inside domain", 
            call. = FALSE)
    }
    if (length(max_iterations) != 1L || !is.numeric(max_iterations) || 
        is.na(max_iterations) || !is.finite(max_iterations) || 
        max_iterations < 1 || max_iterations != floor(max_iterations)) {
        stop("max_iterations must be a positive integer", call. = FALSE)
    }
    if (!is.null(seed)) {
        if (length(seed) != 1L || !is.numeric(seed) || is.na(seed) || 
            !is.finite(seed)) {
            stop("seed must be NULL or one finite number", call. = FALSE)
        }
        set.seed(seed)
    }
    n <- as.integer(n)
    if (n == 0L) 
        return(numeric())
    x <- sort(as.numeric(initial))
    h <- ars_eval_log_density(target, x, log)
    if (any(!is.finite(h))) 
        stop("initial points must have finite log density", call. = FALSE)
    dh <- vapply(x, function(point) ars_eval_derivative(target, 
        point, log, domain[1], domain[2]), numeric(1))
    if (any(diff(h)/diff(x) > dh[-length(dh)] + 1e-05) || any(diff(h)/diff(x) < 
        dh[-1L] - 1e-05)) {
        stop("target is not log-concave near the initial points", 
            call. = FALSE)
    }
    samples <- numeric(n)
    accepted <- 0L
    iterations <- 0L
    while (accepted < n) {
        iterations <- iterations + 1L
        if (iterations > max_iterations) 
