}, test <- function() {
    cat("Running adaptive rejection sampler tests (10,000 draws per distribution).\n")
    set.seed(20261004)
    results <- list()
    run_case <- function(name, sampler, expected_mean, expected_sd, 
        mean_tolerance, sd_tolerance) {
        outcome <- tryCatch({
            values <- sampler()
            observed_mean <- mean(values)
            observed_sd <- sd(values)
            passed <- length(values) == 10000L && abs(observed_mean - 
                expected_mean) <= mean_tolerance && abs(observed_sd - 
                expected_sd) <= sd_tolerance
            list(pass = passed, mean = observed_mean, sd = observed_sd, 
                error = NULL)
        }, error = function(e) list(pass = FALSE, mean = NA_real_, 
            sd = NA_real_, error = conditionMessage(e)))
        status <- if (outcome$pass) 
            "PASS"
        else "FAIL"
        details <- sprintf("mean=%.4f (truth %.4f), sd=%.4f (truth %.4f)", 
            outcome$mean, expected_mean, outcome$sd, expected_sd)
        if (!is.null(outcome$error)) 
            details <- paste(details, "error=", outcome$error)
        cat(sprintf("%s: %s | %s\n", name, status, details))
        results[[name]] <<- outcome$pass
        invisible(outcome)
    }
    normal <- run_case("NORMAL_N(0,1)", function() {
        ars(function(x) dnorm(x, log = TRUE), 10000, c(-1, 0, 
            1), seed = 101)
    }, 0, 1, 0.04, 0.04)
    exponential <- run_case("EXPONENTIAL_RATE_1", function() {
        ars(function(x) dexp(x, log = TRUE), 10000, c(0.5, 1, 
            2), domain = c(0, Inf), seed = 202)
    }, 1, 1, 0.04, 0.04)
    run_case("NORMAL_VECTORIZED_CALLBACK", function() {
        ars(function(x) dnorm(x, mean = 2, sd = 1.5, log = TRUE), 
            10000, c(0.5, 2, 3.5), seed = 303)
    }, 2, 1.5, 0.06, 0.06)
    invalid_input <- inherits(try(ars(function(x) dnorm(x, log = TRUE), 
        -1, c(-1, 0, 1)), silent = TRUE), "try-error")
    nonconcave <- inherits(try(ars(function(x) x^2, 10, c(-1, 
        1), domain = c(-2, 2), log = TRUE), silent = TRUE), "try-error")
    cat(sprintf("INVALID_SAMPLE_COUNT: %s | mean=NA, sd=NA\n", 
        if (invalid_input) 
            "PASS"
        else "FAIL"))
    cat(sprintf("NON_LOG_CONCAVE_TARGET: %s | mean=NA, sd=NA\n", 
        if (nonconcave) 
            "PASS"
        else "FAIL"))
    results[["INVALID_SAMPLE_COUNT"]] <- invalid_input
    results[["NON_LOG_CONCAVE_TARGET"]] <- nonconcave
    if (normal$pass) {
        set.seed(404)
        samples <- ars(function(x) dnorm(x, log = TRUE), 10000, 
            c(-1, 0, 1), seed = 404)
        write.table(samples, file = "/app/normal_samples.txt", 
            row.names = FALSE, col.names = "sample", quote = FALSE)
        cat(sprintf("SAMPLE_FILE: PASS | wrote %d normal samples to /app/normal_samples.txt\n", 
            length(samples)))
    }
    else {
        cat("SAMPLE_FILE: FAIL | normal sampling test did not pass\n")
        results[["SAMPLE_FILE"]] <- FALSE
    }
    cat(sprintf("OVERALL: %s\n", if (all(unlist(results))) 
        "PASS"
    else "FAIL"))
    invisible(all(unlist(results)))
})
