+      x <- c(x, candidate)
+      fx <- c(fx, fc)
+      slope <- c(slope, new_slope)
+      ord <- order(x)
+      x <- x[ord]
+      fx <- fx[ord]
+      slope <- slope[ord]
+      ars_check_concavity(x, fx, slope)
+    }
+  }
+  samples
+}
+
+ars_expect_error <- function(expr, pattern) {
+  message <- tryCatch({
+    force(expr)
+    NA_character_
+  }, error = function(e) conditionMessage(e))
+  !is.na(message) && grepl(pattern, message, ignore.case = TRUE)
+}
+
+test <- function(seed = 20261004, n = 5000L,
+                 sample_file = "/app/normal_samples.txt") {
+  if (length(seed) != 1L || !is.numeric(seed) || is.na(seed) ||
+      !is.finite(seed) || seed != floor(seed)) {
+    stop("'seed' must be a finite integer.", call. = FALSE)
+  }
+  if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) ||
+      n < 1000 || n != floor(n)) {
+    stop("'n' must be an integer of at least 1000 for formal moment tests.",
+         call. = FALSE)
+  }
+  set.seed(seed)
+  results <- list()
+  report <- function(name, passed, samples = numeric(), detail = "") {
+    avg <- if (length(samples)) mean(samples) else NA_real_
+    spread <- if (length(samples) > 1L) sd(samples) else NA_real_
+    line <- sprintf("%s: %s | mean=%.4f, sd=%.4f%s", name,
+                    if (passed) "PASS" else "FAIL", avg, spread,
+                    if (nzchar(detail)) paste0(" | ", detail) else "")
+    cat(line, "\n", sep = "")
+    results[[name]] <<- list(pass = passed, mean = avg, sd = spread, detail = detail)
+  }
+
+  normal <- tryCatch(ars(function(x) dnorm(x, log = TRUE), n,
+                         domain = c(-Inf, Inf), initial = c(-1, 1)),
+                     error = function(e) e)
