+                         col.names = FALSE, quote = FALSE),
+             error = function(e) report("SAMPLE_FILE", FALSE,
+                                         detail = conditionMessage(e)))
+    if (file.exists(sample_file)) {
+      report("SAMPLE_FILE", length(readLines(sample_file)) == length(normal), normal,
+             paste("saved", normalizePath(sample_file, mustWork = FALSE)))
+    }
+  }
+
+  exponential <- tryCatch(ars(function(x) ifelse(x >= 0, -x, -Inf), n,
+                              domain = c(0, Inf), initial = c(0.5, 1.5)),
+                          error = function(e) e)
+  if (inherits(exponential, "error")) {
+    report("EXPONENTIAL_RATE_1", FALSE, detail = conditionMessage(exponential))
+  } else {
