+  }
+
+  gamma_shape2 <- tryCatch(ars(function(x) ifelse(x > 0, log(x) - x, -Inf), n,
+                               domain = c(0, Inf), initial = c(0.5, 1.5)),
+                           error = function(e) e)
+  if (inherits(gamma_shape2, "error")) {
+    report("GAMMA_SHAPE_2", FALSE, detail = conditionMessage(gamma_shape2))
+  } else {
+    ok <- all(gamma_shape2 > 0) && abs(mean(gamma_shape2) - 2) < 0.09 &&
