+# Adaptive rejection sampling (ARS), following Gilks and Wild (1992).
+# The target supplied to ars() is a vectorized log-density by default.
+
+ars_validate_inputs <- function(target, n, domain, initial, log, max_iter) {
+  if (!is.function(target)) {
+    stop("'target' must be a vectorized function of one numeric argument.", call. = FALSE)
+  }
+  if (length(n) != 1L || !is.numeric(n) || is.na(n) || !is.finite(n) ||
+      n < 0 || n != floor(n)) {
+    stop("'n' must be a single non-negative integer.", call. = FALSE)
+  }
+  if (length(log) != 1L || is.na(log) || !is.logical(log)) {
+    stop("'log' must be TRUE or FALSE.", call. = FALSE)
+  }
+  if (length(max_iter) != 1L || !is.numeric(max_iter) || is.na(max_iter) ||
+      !is.finite(max_iter) || max_iter < 1 || max_iter != floor(max_iter)) {
+    stop("'max_iter' must be a positive integer.", call. = FALSE)
+  }
+  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) ||
+      any(is.nan(domain)) || domain[1L] >= domain[2L]) {
+    stop("'domain' must be c(lower, upper), with lower < upper.", call. = FALSE)
+  }
+  if (length(initial) < 2L || !is.numeric(initial) || any(!is.finite(initial)) ||
+      any(diff(initial) <= 0)) {
+    stop("'initial' must contain at least two finite, strictly increasing points.",
+         call. = FALSE)
+  }
+  if (any(initial <= domain[1L] | initial >= domain[2L])) {
+    stop("Every initial point must lie strictly inside 'domain'.", call. = FALSE)
+  }
+  invisible(TRUE)
+}
+
+ars_evaluate <- function(target, x, log) {
+  value <- tryCatch(target(x), error = function(e) {
+    stop("Target evaluation failed: ", conditionMessage(e), call. = FALSE)
+  })
+  if (!is.numeric(value) || length(value) != length(x)) {
+    stop("'target' must return one numeric value for each input point.", call. = FALSE)
+  }
+  if (log) {
+    y <- as.numeric(value)
+  } else {
+    if (any(is.na(value)) || any(value < 0)) {
+      stop("A density function must return non-negative, non-missing values.", call. = FALSE)
+    }
+    y <- log(as.numeric(value))
+  }
+  if (any(is.nan(y)) || any(y == Inf)) {
+    stop("The log density must be finite or -Inf at evaluated points.", call. = FALSE)
+  }
+  y
+}
+
+ars_derivatives <- function(target, x, fx, log, domain) {
+  # Symmetric finite differences are used only to form the tangent envelope.
+  h <- .Machine$double.eps^(1 / 3) * pmax(1, abs(x))
+  can_left <- x - h > domain[1L]
+  can_right <- x + h < domain[2L]
+  left <- rep(NA_real_, length(x))
+  right <- rep(NA_real_, length(x))
+  if (any(can_left)) {
+    left[can_left] <- ars_evaluate(target, x[can_left] - h[can_left], log)
+  }
+  if (any(can_right)) {
+    right[can_right] <- ars_evaluate(target, x[can_right] + h[can_right], log)
+  }
+  slope <- numeric(length(x))
+  both <- can_left & can_right
+  slope[both] <- (right[both] - left[both]) / (2 * h[both])
+  only_left <- can_left & !can_right
+  slope[only_left] <- (fx[only_left] - left[only_left]) / h[only_left]
+  only_right <- !can_left & can_right
+  slope[only_right] <- (right[only_right] - fx[only_right]) / h[only_right]
+  if (any(!is.finite(slope))) {
+    stop("Could not obtain finite log-density slopes at initial/adaptive points.",
+         call. = FALSE)
+  }
+  slope
+}
+
+ars_check_concavity <- function(x, fx, slope, tolerance = 1e-6) {
+  ord <- order(x)
+  x <- x[ord]
+  fx <- fx[ord]
+  slope <- slope[ord]
+  if (any(!is.finite(fx))) {
+    stop("Initial/adaptive points must have finite log density.", call. = FALSE)
+  }
+  secant <- diff(fx) / diff(x)
+  if (any(diff(slope) > tolerance * (1 + abs(slope[-1L])))) {
+    stop("Log-concavity check failed: estimated log-density slopes increase.",
+         call. = FALSE)
+  }
+  if (length(secant) > 1L && any(diff(secant) > tolerance * (1 + abs(secant[-1L])))) {
+    stop("Log-concavity check failed: adjacent secant slopes increase.",
+         call. = FALSE)
+  }
+  if (any(slope[-length(slope)] < secant - tolerance * (1 + abs(secant))) ||
+      any(slope[-1L] > secant + tolerance * (1 + abs(secant)))) {
+    stop("Log-concavity check failed: tangent slopes contradict the log-density.",
+         call. = FALSE)
+  }
+  invisible(TRUE)
+}
+
+ars_intersections <- function(x, fx, slope) {
+  n <- length(x)
+  z <- numeric(n - 1L)
+  for (i in seq_len(n - 1L)) {
+    denominator <- slope[i] - slope[i + 1L]
+    if (denominator <= 0) {
+      stop("Log-concavity check failed: tangent slopes are not decreasing.",
+           call. = FALSE)
+    }
+    z[i] <- (fx[i + 1L] - fx[i] + slope[i] * x[i] -
+               slope[i + 1L] * x[i + 1L]) / denominator
+    if (!is.finite(z[i]) || z[i] <= x[i] || z[i] >= x[i + 1L]) {
+      stop("Invalid tangent intersection; target may not be log-concave.",
+           call. = FALSE)
+    }
+  }
+  z
+}
+
+ars_log_integral <- function(a, b, left, right) {
+  # Integral of exp(a + b*x) from left to right, returned on log scale.
+  if (b == 0) return(a + log(right - left))
+  endpoints <- c(a + b * left, a + b * right)
+  hi <- max(endpoints)
+  lo <- min(endpoints)
+  hi + log1p(-exp(lo - hi)) - log(abs(b))
+}
+
+ars_build_hull <- function(x, fx, slope, domain) {
+  z <- ars_intersections(x, fx, slope)
+  bounds <- c(domain[1L], z, domain[2L])
+  seg <- seq_along(x)
+  left <- bounds[seq_along(x)]
+  right <- bounds[seq_along(x) + 1L]
+  log_mass <- vapply(seg, function(i) {
+    ars_log_integral(fx[i] - slope[i] * x[i], slope[i], left[i], right[i])
+  }, numeric(1L))
+  if (any(!is.finite(log_mass))) {
+    stop("The tangent envelope has a non-finite segment mass; check the domain and tails.",
+         call. = FALSE)
+  }
+  list(left = left, right = right, log_mass = log_mass, z = z)
+}
+
+ars_draw_hull <- function(x, fx, slope, hull) {
+  weights <- exp(hull$log_mass - max(hull$log_mass))
+  segment <- sample.int(length(weights), size = 1L, prob = weights)
+  a <- fx[segment] - slope[segment] * x[segment]
+  b <- slope[segment]
+  left <- hull$left[segment]
+  right <- hull$right[segment]
+  u <- runif(1L)
+  if (abs(b) < 1e-12) {
+    proposal <- left + u * (right - left)
+  } else {
+    lo <- b * left
+    hi <- b * right
+    if (b > 0) {
+      proposal <- log(exp(lo) + u * (exp(hi) - exp(lo))) / b
+    } else {
+      proposal <- log(exp(hi) + u * (exp(lo) - exp(hi))) / b
+    }
+  }
+  list(x = proposal, upper = a + b * proposal, segment = segment)
+}
+
+ars <- function(target, n, domain = c(-Inf, Inf), initial = NULL,
+                log = TRUE, max_iter = max(10000L, 1000L * max(1L, n))) {
+  if (is.null(initial)) {
+    if (is.finite(domain[1L]) && is.finite(domain[2L])) {
+      initial <- domain[1L] + (domain[2L] - domain[1L]) * c(1 / 3, 2 / 3)
+    } else if (is.finite(domain[1L])) {
+      initial <- domain[1L] + c(1, 2)
+    } else if (is.finite(domain[2L])) {
+      initial <- domain[2L] - c(2, 1)
+    } else {
+      initial <- c(-1, 1)
+    }
+  }
+  ars_validate_inputs(target, n, domain, initial, log, max_iter)
+  if (n == 0L) return(numeric(0L))
+
+  x <- sort(as.numeric(initial))
+  fx <- ars_evaluate(target, x, log)
+  if (any(!is.finite(fx))) {
+    stop("Initial points must have finite log density and lie inside the support.",
+         call. = FALSE)
+  }
+  slope <- ars_derivatives(target, x, fx, log, domain)
+  ars_check_concavity(x, fx, slope)
+
+  samples <- numeric(n)
+  accepted <- 0L
+  iterations <- 0L
+  while (accepted < n) {
+    iterations <- iterations + 1L
+    if (iterations > max_iter) {
+      stop("Maximum proposal count reached before obtaining the requested samples.",
+           call. = FALSE)
+    }
+    hull <- ars_build_hull(x, fx, slope, domain)
+    draw <- ars_draw_hull(x, fx, slope, hull)
+    candidate <- draw$x
+    fc <- ars_evaluate(target, candidate, log)
+    if (is.na(fc) || fc == Inf) {
+      stop("Invalid log density encountered during sampling.", call. = FALSE)
+    }
+    if (fc > draw$upper + 1e-7 * (1 + abs(draw$upper))) {
+      stop("Log-concavity check failed: target exceeds its tangent upper hull.",
+           call. = FALSE)
+    }
+    if (log(runif(1L)) <= fc - draw$upper) {
+      accepted <- accepted + 1L
+      samples[accepted] <- candidate
+    }
+    # Each proposal enriches the hull; this also enables a secant/slope
+    # concavity check at newly explored regions, even when rejected.
+    if (is.finite(fc) && all(abs(x - candidate) > 1e-10 * (1 + abs(candidate)))) {
+      new_slope <- ars_derivatives(target, candidate, fc, log, domain)
+      x <- c(x, candidate)
+      fx <- c(fx, fc)
+      slope <- c(slope, new_slope)
+      ord <- order(x)
+      x <- x[ord]
+      fx <- fx[ord]
+      slope <- slope[ord]
+      ars_check_concavity(x, fx, slope)
+    }
+  }
+  samples
+}
+
+ars_expect_error <- function(expr, pattern) {
+  message <- tryCatch({
+    force(expr)
+    NA_character_
+  }, error = function(e) conditionMessage(e))
+  !is.na(message) && grepl(pattern, message, ignore.case = TRUE)
+}
+
